function addLinks(){document.querySelectorAll('#nr-programs .nr-programs .nr-program').forEach((p,i)=>{if(!desks[i])return;let a=p.querySelector('.desk-archive-link');if(!a){a=document.createElement('a');a.className='desk-archive-link';a.style.cssText='display:block;font-size:12px;font-weight:500;margin-top:6px;color:#215c50;text-decoration:underline';a.onclick=e=>{e.stopPropagation();if(location.hash===a.hash)openDesk();};p.append(a);}a.href='section.html?desk='+desks[i][0]+'&lang='+(document.documentElement.dataset.lang||'ko');a.textContent=label()+' ↗';a.setAttribute('aria-label',desks[i][1]+' '+label());});}
